  'sails.hero.description': 'Velas tensadas de diseño moderno que combinan protección UV con una estética espectacular. La solución más elegante para grandes espacios.',
  'sails.hero.cta': 'Solicitar Presupuesto',
  'sails.shapes.heading': 'Formas y Opciones',
